<!-- Problem detail management view. -->
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useProblemDetailStore } from '../stores/problemDetail';
import { useProblemManagementStore } from '../stores/problemManagement';
import type { Difficulty } from '../types';
const route = useRoute(); const router = useRouter(); const id = String(route.params.problemId); const problem = useProblemDetailStore(); const management = useProblemManagementStore();
const editing = ref(false); const form = reactive({ title: '', difficulty: 'EASY' as Difficulty, internalNote: '' }); const categoryIds = ref<string[]>([]); const noteIds = ref<string[]>([]);
const edit = () => { if (!problem.problem) return; Object.assign(form, { title: problem.problem.title, difficulty: problem.problem.difficulty, internalNote: problem.problem.internalNote ?? '' }); editing.value = true; };
const save = async () => { if (await problem.update(id, { ...form, internalNote: form.internalNote || null })) editing.value = false; };
const saveCategories = async () => { if (await management.saveCategories(id, categoryIds.value)) await problem.fetch(id); };
const saveNotes = async () => { if (await management.saveNotes(id, noteIds.value)) await problem.fetch(id); };
const remove = async () => { if (window.confirm('确认删除这道题目吗？此操作不可撤销。') && await problem.remove(id)) await router.push(route.query.categoryId ? `/categories/${String(route.query.categoryId)}/problems` : '/categories'); };
onMounted(async () => { await Promise.all([problem.fetch(id), management.fetchCategories(), management.fetchNotes()]); if (problem.problem) { categoryIds.value = problem.problem.categories.map((item) => item.id); noteIds.value = problem.problem.notes.map((item) => item.id); } });
const labels: Record<Difficulty, string> = { EASY: '简单', MEDIUM: '中等', HARD: '困难' };
</script>
<template><section class="mx-auto max-w-5xl p-5 md:p-10"><button class="mb-5 underline" @click="router.back">← 返回列表</button><p v-if="problem.loading" role="status">正在加载题目…</p><p v-else-if="problem.error" role="alert">{{ problem.error }}</p><template v-else-if="problem.problem"><header class="flex flex-wrap justify-between gap-3 border-b border-[var(--color-border)] pb-5"><div><h2 class="text-3xl font-semibold">{{ problem.problem.title }}</h2><span class="text-sm text-[var(--color-accent)]">{{ labels[problem.problem.difficulty] }}</span></div><div class="flex gap-3"><button class="border px-3 py-2" @click="edit">编辑题目</button><button class="text-red-700 underline" @click="remove">删除题目</button></div></header><form v-if="editing" class="mt-5 space-y-3 border p-5" @submit.prevent="save"><input v-model="form.title" required aria-label="题目标题" class="w-full border bg-transparent p-2" /><select v-model="form.difficulty" aria-label="题目难度" class="border bg-transparent p-2"><option value="EASY">简单</option><option value="MEDIUM">中等</option><option value="HARD">困难</option></select><textarea v-model="form.internalNote" aria-label="内部笔记" rows="4" class="w-full border bg-transparent p-2" /><p v-if="problem.saveError" role="alert" class="text-red-700">{{ problem.saveError }}</p><button :disabled="problem.saving" class="bg-[var(--color-accent)] px-4 py-2 text-white">{{ problem.saving ? '保存中…' : '保存编辑' }}</button></form><p v-if="problem.deleteError" role="alert" class="mt-3 text-red-700">{{ problem.deleteError }}</p><div class="mt-6 grid gap-6 lg:grid-cols-2"><article class="border p-5"><h3 class="font-semibold">内部笔记</h3><p v-if="!problem.problem.internalNote" class="mt-3 opacity-60">暂无内部笔记。</p><div v-else class="prose mt-3" v-html="problem.problem.internalNote"></div></article><article class="space-y-3 border p-5"><h3 class="font-semibold">管理分类</h3><p v-if="!problem.problem.categories.length" class="text-sm opacity-60">暂无关联分类。</p><select v-model="categoryIds" multiple aria-label="题目分类" class="w-full border bg-transparent p-2"><option v-for="item in management.categories" :key="item.id" :value="item.id">{{ item.name }}</option></select><p v-if="management.categoryError" role="alert" class="text-red-700">{{ management.categoryError }}</p><button :disabled="management.savingCategories" class="border px-3 py-2" @click="saveCategories">保存分类</button></article><article class="space-y-3 border p-5 lg:col-span-2"><h3 class="font-semibold">关联题解笔记</h3><p v-if="!problem.problem.notes.length" class="text-sm opacity-60">暂无关联题解笔记。</p><div class="flex flex-wrap gap-2"><RouterLink v-for="item in problem.problem.notes" :key="item.id" :to="`/notes/${item.id}`" class="border px-3 py-2">{{ item.title }}</RouterLink></div><select v-model="noteIds" multiple aria-label="关联题解笔记" class="w-full border bg-transparent p-2"><option v-for="item in management.notes" :key="item.id" :value="item.id">{{ item.title }}</option></select><p v-if="management.noteError" role="alert" class="text-red-700">{{ management.noteError }}</p><button :disabled="management.savingNotes" class="border px-3 py-2" @click="saveNotes">保存笔记关联</button></article></div></template></section></template>
